const incoming = $input.first().json;
const body = incoming.body ?? incoming;
if (!Array.isArray(body.alerts)) throw new Error('SCRUM76: payload sin lista alerts');
const memo = $getWorkflowStaticData('global');
memo.byFingerprint ??= {};
const output = [];
for (const alert of body.alerts) {
  const status = String(alert.status ?? body.status ?? '').toLowerCase();
  if (!['firing','resolved'].includes(status)) throw new Error('Estado invalido');
  const fingerprint = String(alert.fingerprint ?? '').trim();
  if (!/^[a-zA-Z0-9_-]{6,128}$/.test(fingerprint)) throw new Error('Fingerprint faltante o invalido');
  const severity = String(alert.labels?.severity ?? '').toLowerCase();
  if (!['critical','warning','info'].includes(severity)) throw new Error('Severidad invalida');
  const prior = memo.byFingerprint[fingerprint];
  if (status === 'firing' && prior?.issueId) continue;
  if (status === 'resolved' && !prior?.issueId) continue;
  const title = String(alert.labels?.alertname ?? 'SinNombre').slice(0,120);
  const instance = String(alert.labels?.instance ?? 'sin instancia').slice(0,160);
  const details = String(alert.annotations?.description ?? alert.annotations?.summary ?? 'Sin descripcion').slice(0,2000);
  output.push({json:{status,fingerprint,severity,title,instance,
    summary:`[Prometheus] ${title} - ${instance}`.slice(0,120),
    description:`Alerta de Prometheus/Alertmanager\\nEstado: ${status}\\nFingerprint: ${fingerprint}\\nSeveridad: ${severity}\\nInstancia: ${instance}\\nDetalle: ${details}`,
    mantis_priority:severity==='critical'?'urgent':severity==='warning'?'high':'normal',
    mantis_severity:severity==='critical'?'major':severity==='warning'?'minor':'text',
    issueId:prior?.issueId ?? null,
    resolvedAt:String(alert.endsAt ?? new Date().toISOString())}});
}
return output;

const payload=$input.item.json;
const issueId=payload.issue?.id;
if (!issueId) throw new Error('Mantis no devolvio issue.id');
const original=$('Validar y deduplicar').item.json;
const memo=$getWorkflowStaticData('global');
memo.byFingerprint ??= {};
memo.byFingerprint[original.fingerprint]={issueId,at:new Date().toISOString()};
return {json:{result:'CREADA',fingerprint:original.fingerprint,issueId,link:`http://localhost:8990/view.php?id=${issueId}`}};

